"""Simple deterministic AI driver.

The engine never imports this module; `main.py` injects an instance. A human
driver could implement the same three methods and be swapped in unchanged.
"""

RESERVE = 100          # keep this much cash in hand when buying
BUILD_RESERVE = 300    # only build when comfortably liquid


class SimpleAI:
    def decide_buy(self, game, player, space):
        price = space.price
        if price is None or player.cash < price:
            return False
        # Always complete a color group if we can.
        if space.group in game.board.group_members:
            members = game.board.spaces_in_group(space.group)
            owned = sum(1 for i in members if game.state[i].owner == player.index)
            if owned == len(members) - 1:
                return True
        # Otherwise buy if we can keep a reserve.
        return player.cash - price >= RESERVE

    def manage(self, game, player):
        # Unmortgage anything we can comfortably afford.
        for i, ps in enumerate(game.state):
            if ps.owner == player.index and ps.mortgaged:
                cost = int(game.board.space(i).price // 2 * 1.1)
                if player.cash - cost >= BUILD_RESERVE:
                    game.unmortgage(i, player)
        # Build evenly on full groups while liquid.
        changed = True
        while changed:
            changed = False
            for i, ps in enumerate(game.state):
                if ps.owner != player.index:
                    continue
                if player.cash - game.board.space(i).house_cost < BUILD_RESERVE:
                    continue
                if game.can_build(i, player):
                    game.build_house(i, player)
                    changed = True

"""Rendering helpers. Pure functions over game state; no rules live here."""

from board import PROPERTY_GROUPS


def render_log(game, limit=None):
    lines = list(game.log)
    if limit is not None:
        lines = lines[-limit:]
    return "\n".join(lines)


def render_standings(game):
    rows = []
    for p in sorted(game.players, key=lambda p: p.net_worth(game), reverse=True):
        status = "BANKRUPT" if p.bankrupt else f"${p.cash}"
        props = sum(1 for ps in game.state if ps.owner == p.index)
        rows.append(
            f"  {p.name:<10} cash={status:<10} properties={props:<3} "
            f"net_worth=${p.net_worth(game)}"
        )
    return "\n".join(rows)


def render_board(game):
    """A compact one-line-per-side view of the board."""
    out = []
    for sp in game.board.spaces:
        ps = game.state[sp.index]
        if ps.owner is None:
            owner = "-"
        else:
            owner = game.players[ps.owner].name
            if ps.mortgaged:
                owner += "(M)"
            if ps.houses == 5:
                owner += "[H]"
            elif ps.houses:
                owner += f"[{ps.houses}]"
        out.append(f"  {sp.index:>2} {sp.name:<24} {owner}")
    return "\n".join(out)


def render_summary(game):
    lines = []
    lines.append("=" * 60)
    lines.append("MONOPOLY — final standings")
    lines.append("=" * 60)
    lines.append(render_standings(game))
    lines.append("-" * 60)
    if game.winner is not None:
        lines.append(f"WINNER: {game.winner.name} "
                     f"(net worth ${game.winner.net_worth(game)})")
    lines.append(f"Turns played: {game.turn}")
    return "\n".join(lines)

"""Simple AI driver: decides purchases, raises cash, and builds houses.

The engine (`game.Game`) never imports this module; it is passed in as a
pluggable driver, so a human REPL could replace it without touching rules.
"""


class AIPlayer:
    def __init__(self, reserve: int = 100, build_reserve: int = 300):
        self.reserve = reserve
        self.build_reserve = build_reserve

    # -- purchasing ---------------------------------------------------------
    def decide_buy(self, game, player, idx: int) -> bool:
        sp = game.board.spaces[idx]
        price = sp.price
        if price is None or player.cash < price:
            return False

        # Completing a color group is always worth it.
        if sp.group and sp.group not in ("railroad", "utility"):
            members = game.board.spaces_in_group(sp.group)
            owned = sum(1 for i in members if game.props[i].owner == player.index)
            if owned == len(members) - 1:
                return True

        # Railroads/utilities are cheap income; grab them when comfortable.
        if sp.kind in ("railroad", "utility") and player.cash >= price + 50:
            return True

        # Otherwise buy if we keep a cash cushion.
        if player.cash - price >= self.reserve:
            return True

        # Cheap early properties are worth stretching for.
        if price <= 120 and player.cash >= price:
            return True
        return False

    # -- raising cash when a debt is due ------------------------------------
    def manage_assets(self, game, player, needed: int) -> None:
        guard = 0
        while player.cash < needed and guard < 200:
            guard += 1
            if not self._sell_one_house(game, player):
                break
        guard = 0
        while player.cash < needed and guard < 200:
            guard += 1
            if not self._mortgage_one(game, player):
                break

    def _sell_one_house(self, game, player) -> bool:
        best = None
        for i, st in enumerate(game.props):
            if st.owner == player.index and st.houses > 0:
                if best is None or st.houses > game.props[best].houses:
                    best = i
        if best is None:
            return False
        return game.sell_house(player, best)

    def _mortgage_one(self, game, player) -> bool:
        for i, st in enumerate(game.props):
            if st.owner == player.index and not st.mortgaged and st.houses == 0:
                if game.mortgage(player, i):
                    return True
        return False

    # -- building -----------------------------------------------------------
    def manage_build(self, game, player) -> None:
        if player.cash < 500:
            return
        for group in list(game.board.group_members):
            if group in ("railroad", "utility"):
                continue
            members = game.board.spaces_in_group(group)
            if not all(game.props[i].owner == player.index for i in members):
                continue
            if any(game.props[i].mortgaged for i in members):
                continue
            guard = 0
            while guard < 40:
                guard += 1
                minh = min(game.props[i].houses for i in members)
                if minh >= 5:
                    break
                candidates = [i for i in members if game.props[i].houses == minh]
                idx = candidates[0]
                cost = game.board.spaces[idx].house_cost or 0
                if player.cash - cost < self.build_reserve:
                    break
                if not game.build_house(player, idx):
                    break

